    });

    test('should contain the channel info button', () => {
        const wrapper = shallowWithIntl(
            <ChannelHeader {...populatedProps}/>,
        );
        expect(wrapper.contains(
            <ChannelInfoButton channel={populatedProps.channel}/>,
        )).toEqual(true);
    });
});

