.AlertBanner {
    display: flex;
    overflow: hidden;
    align-items: flex-start;
    padding: 14px;
    border: 1px solid;
    border-radius: 4px;
}

.AlertBanner__icon {
    font-size: 24px;
    line-height: 24px;

    i {
        display: contents;

        &::before {
            margin: 0;
        }
    }
}

.AlertBanner__body {
    flex-flow: column;
    flex-grow: 1;
    flex-shrink: 1;
    margin-left: 10px;
    font-size: 14px;
}

.AlertBanner__title {
    font-weight: 600;
    line-height: 24px;
}

.AlertBanner__actionButtons {
    margin-top: 12px;
    font-family: 'Open Sans';

    .AlertBanner__buttonLeft {
        &:hover {
            background: #1156b2;
        }

        padding: 10px 16px;
        border: none;
        background: var(--denim-button-bg);
        border-radius: 4px;
        color: white;
        font-size: 12px;
        font-weight: 600;
    }

    .AlertBanner__buttonRight {
        &:hover {
            background: #1c58d91f;
        }

        padding: 10px 16px;
        border: none;
        margin-left: 4px;
        background: rgba(28, 88, 217, 0.08);
        border-radius: 4px;
        color: #1c58d9;
    }
}

.AlertBanner__message {
    margin-top: 8px;
    line-height: 20px;
}

.AlertBanner__closeButton {
    display: flex;
    padding: 3px;
    border: none;
    background: none;
    border-radius: 4px;

    i {
        font-size: 18px;
        line-height: 16px;

        &::before {
            margin: 0;
        }
    }

    &:hover {
        background: rgba(0, 0, 0, 0.08);
    }
}

.AlertBanner--app {
    &.danger {
        border-color: rgba(var(--error-text-color-rgb), 0.24);
        background: rgba(var(--error-text-color-rgb), 0.08);

        .AlertBanner__icon i {
            color: var(--error-text);
        }
    }

    &.info {
        border-color: rgba(var(--sidebar-text-active-border-rgb), 0.24);
        background: rgba(var(--sidebar-text-active-border-rgb), 0.08);

        .AlertBanner__icon i {
            color: var(--sidebar-text-active-border);
        }
    }

    &.warning {
        border-color: rgba(var(--away-indicator-rgb), 0.24);
        background: rgba(var(--away-indicator-rgb), 0.08);

        .AlertBanner__icon i {
            color: var(--away-indicator);
        }
    }

    &.success {
        border-color: rgba(var(--online-indicator-rgb), 0.16);
        background: rgba(var(--online-indicator-rgb), 0.08);

        .AlertBanner__icon i {
            color: var(--denim-status-online);
        }
    }

    .AlertBanner__body {
        color: var(--center-channel-color);
    }

    .AlertBanner__closeButton {
        i {
            color: rgba(var(--center-channel-color-rgb), 0.56);
        }
    }
}

.AlertBanner--sys {
    &.danger {
        border-color: rgba(var(--sys-error-text-color-rgb), 0.24);
        background: rgba(var(--sys-error-text-color-rgb), 0.08);

        .AlertBanner__icon i {
            color: var(--sys-error-text);
        }
    }

    &.info {
        border-color: rgba(var(--sys-sidebar-text-active-border-rgb), 0.24);
        background: rgba(var(--sys-sidebar-text-active-border-rgb), 0.08);

        .AlertBanner__icon i {
            color: var(--sys-sidebar-text-active-border);
        }
    }

    &.warning {
        border-color: rgba(var(--sys-away-indicator-rgb), 0.24);
        background: rgba(var(--sys-away-indicator-rgb), 0.08);

        .AlertBanner__icon i {
            color: var(--sys-away-indicator);
        }
    }

    &.success {
        border-color: rgba(var(--sys-online-indicator-rgb), 0.16);
        background: rgba(var(--sys-online-indicator-rgb), 0.08);

        .AlertBanner__icon i {
            color: var(--sys-online-indicator);
        }
    }

    .AlertBanner__body {
        color: var(--sys-center-channel-color);
    }

    .AlertBanner__closeButton {
        i {
            color: rgba(var(--sys-center-channel-color-rgb), 0.56);
        }
    }
}

